<div class="page-heading"><div><span class="eyebrow dark">Operação</span><h1>Projetos</h1><p><?= count($projects) ?> projeto(s) com acompanhamento de prazo, progresso e valores.</p></div><a class="button button-primary" href="<?= url('/projects/create') ?>">+ Novo projeto</a></div>
<?php if($projects===[]): ?><section class="panel empty-module"><span class="empty-module-icon">P</span><h2>Nenhum projeto cadastrado</h2><p>Marque um lead como contratado e crie o primeiro projeto.</p><a class="button button-primary" href="<?= url('/projects/create') ?>">Criar projeto</a></section><?php else: ?>
<div class="project-overview"><?php foreach(['Briefing','Layout','Desenvolvimento','Homologação','Entregue'] as $stage): ?><span><b><?= count(array_filter($projects,fn($p)=>$p['status']===$stage)) ?></b><?= e($stage) ?></span><?php endforeach; ?></div>
<div class="kanban"><?php foreach(['Briefing','Layout','Desenvolvimento','Homologação','Entregue'] as $stage): ?><section><header><span><?= e($stage) ?></span><b><?= count(array_filter($projects,fn($p)=>$p['status']===$stage)) ?></b></header><?php foreach(array_filter($projects,fn($p)=>$p['status']===$stage) as $project): ?><article class="project-card"><div class="project-card-head"><small><?= e($project['codigo']) ?></small><a href="<?= url('/projects/edit?id='.(int)$project['id']) ?>">Editar</a></div><h3><?= e($project['nome']) ?></h3><p><?= e($project['nome_empresa']) ?></p><div class="project-values"><span>Valor total<strong>R$ <?= number_format((float)$project['valor_total'],2,',','.') ?></strong></span><span>Saldo<strong>R$ <?= number_format((float)$project['saldo'],2,',','.') ?></strong></span></div><div class="progress"><i style="width:<?= (int)$project['progresso'] ?>%"></i></div><div><span><?= (int)$project['progresso'] ?>%</span><strong><?= $project['data_entrega'] ? date('d/m/Y',strtotime($project['data_entrega'])) : 'Sem entrega' ?></strong></div><a class="project-open" href="<?= url('/projects/edit?id='.(int)$project['id']) ?>">Ver e editar projeto</a></article><?php endforeach; ?></section><?php endforeach; ?></div>
<?php endif; ?>
